import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  Future<List<CurrencyModel>>? _currencyListFuture;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;
  bool _hasMore = true;
  bool _isLoadingMore = false;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _loadInitialPage();
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _loadInitialPage() async {
    final currencyRepository = context.read<CurrencyRepository>();

    _currencyListFuture = currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD')).then((CurrencyPage page) {
      _allCurrencies = page.items;
      _currentPage = page.page + 1;
      _hasMore = page.hasMore;
      _filteredCurrenciesNotifier = ValueNotifier(_allCurrencies);

      _fadeController.forward(); // запускаем анимацию

      currencyRepository.saveCurrencyList(_allCurrencies);

      return _allCurrencies;
    });
  }

  Future<void> _loadMore() async {
    if (_isLoadingMore || !_hasMore) return;

    setState(() {
      _isLoadingMore = true;
    });

    final currencyRepository = context.read<CurrencyRepository>();
    final pageRequest = CurrencyPageRequest(base: 'USD', page: _currentPage);

    try {
      final page = await currencyRepository.fetchRates(pageRequest);
      if (page.items.isNotEmpty) {
        setState(() {
          _allCurrencies.addAll(page.items);
          _filteredCurrenciesNotifier.value = List<CurrencyModel>.from(_allCurrencies);
          _currentPage = page.page + 1;
          _hasMore = page.hasMore;
        });

        currencyRepository.saveCurrencyList(_allCurrencies);
      } else {
        setState(() {
          _hasMore = false;
        });
      }
    } finally {
      if (mounted) {
        setState(() {
          _isLoadingMore = false;
        });
      }
    }
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = List<CurrencyModel>.from(result);
  }

  @override
  Widget build(BuildContext context) {
    final loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.currencyRate)),
      body: FutureBuilder<List<CurrencyModel>>(
        future: _currencyListFuture,
        builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
          if (!snapshot.hasData) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> data, _) {
                      return ListView.builder(
                        itemCount: data.length + (_hasMore || _isLoadingMore ? 1 : 0),
                        itemBuilder: (BuildContext context, int index) {
                          if (!_hasMore && index == data.length - 1) {
                            // Последняя страница — ничего не добавляем
                            return const SizedBox.shrink();
                          }

                          if (_isLoadingMore && index == data.length) {
                            return Padding(
                              padding: const EdgeInsets.only(top: 20, bottom: 8),
                              child: Center(
                                child: Text(
                                  loc.loadingMore,
                                  style: context.fonts.regular12.copyWith(color: context.colors.stormyGrey),
                                ),
                              ),
                            );
                          }

                          final CurrencyModel currency = data[index];

                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                      );
                    },
                  ),
                ),
                if (_hasMore && !_isLoadingMore)
                  Padding(
                    padding: const EdgeInsets.only(bottom: 16),
                    child: ElevatedButton(
                      onPressed: _loadMore,
                      child: Text(loc.showMore),
                    ),
                  ),
              ],
            ),
          );
        },
      ),
    );
  }
}
