30:     _loadInitialPage();
31:   }
32: 
33:   @override
34:   void dispose() {
35:     _filteredCurrenciesNotifier.dispose();
36:     _fadeController.dispose();
37:     super.dispose();
38:   }
39: 
40:   void _initAnimation() {
41:     _fadeController = AnimationController(
42:       duration: Duration(milliseconds: 400),
43:       vsync: this,
44:     );
45:   }
46: 
47:   Future<void> _loadInitialPage() async {
48:     final currencyRepository = context.read<CurrencyRepository>();
49: 
50:     _currencyListFuture = currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD')).then((CurrencyPage page) {
51:       _allCurrencies = page.items;
52:       _currentPage = page.page + 1;
53:       _hasMore = page.hasMore;
54:       _filteredCurrenciesNotifier = ValueNotifier(_allCurrencies);
55: 
56:       _fadeController.forward(); // запускаем анимацию
57: 
58:       currencyRepository.saveCurrencyList(_allCurrencies);
59: 
60:       return _allCurrencies;
61:     });
62:   }
63: 
64:   Future<void> _loadMore() async {
65:     if (_isLoadingMore || !_hasMore) return;
66: 
67:     setState(() {
68:       _isLoadingMore = true;
69:     });
70: 
71:     final currencyRepository = context.read<CurrencyRepository>();
72:     final pageRequest = CurrencyPageRequest(base: 'USD', page: _currentPage);
73: 
74:     try {
75:       final page = await currencyRepository.fetchRates(pageRequest);
76:       if (page.items.isNotEmpty) {
77:         setState(() {
78:           _allCurrencies.addAll(page.items);
79:           _filteredCurrenciesNotifier.value = List<CurrencyModel>.from(_allCurrencies);
80:           _currentPage = page.page + 1;
81:           _hasMore = page.hasMore;
82:         });
83: 
84:         currencyRepository.saveCurrencyList(_allCurrencies);
85:       } else {
86:         setState(() {
87:           _hasMore = false;
88:         });
89:       }
90:     } finally {
91:       if (mounted) {
92:         setState(() {
93:           _isLoadingMore = false;
94:         });
95:       }
96:     }
97:   }
98: 
99:   void _filterCurrencies(String query) {
100:     final String lowerQuery = query.toLowerCase();
101:     final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
102:       return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
103:     });
104: 
105:     _filteredCurrenciesNotifier.value = List<CurrencyModel>.from(result);
106:   }
107: 
108:   @override
