import '../mocks/repository.mocks.dart';

import 'widget.dart';

Future<void> main() async {
  await initializeDateFormatting(AppConstants.ruLocale, null);

  group('CurrencyListPage', () {
    final MockCurrencyRepository mockCurrencyRepository = MockCurrencyRepository();

    final currencyItems = [
      CurrencyModel(
        id: '1',
        nominal: 1,
        name: 'Доллар США',
        symbol: 'USD',
        value: 78.4181,
        previousValue: 78.5,
      ),
      CurrencyModel(
        id: '2',
        nominal: 1,
        name: 'Евро',
        symbol: 'EUR',
        value: 92.7440,
        previousValue: 92.2,
      ),
    ];

    setUp(() {
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => CurrencyPage(items: currencyItems, page: 0, hasMore: false));
      when(mockCurrencyRepository.saveCurrencyList(any)).thenAnswer((_) async {});
    });

    testWidgets('should display all currency items when loaded', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();

      expect(find.text('USD'), findsOneWidget);
      expect(find.text('EUR'), findsOneWidget);
      expect(find.text('JPY'), findsNothing);
      expect(find.byType(CurrencyCard), findsNWidgets(currencyItems.length));
    });

    testWidgets('should navigate to detail page when currency card is tapped', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();
      await tester.tap(find.byType(CurrencyCard).first);
      await tester.pumpAndSettle();

      expect(find.byType(CurrencyDetailPage), findsOneWidget);
    });

    testWidgets('should filter currencies when search text is entered', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();
      await tester.enterText(find.byType(TextField), 'Евро');
      await tester.pump();

      expect(find.byType(CurrencyCard), findsOneWidget);
    });

    testWidgets('should not show "Show more" button when hasMore is false', (WidgetTester tester) async {
      // hasMore = false — кнопка не должна отображаться
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => CurrencyPage(items: currencyItems, page: 0, hasMore: false));

      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();
      expect(find.byType(ElevatedButton), findsNothing);
    });

    testWidgets('should load next page when "Show more" is tapped', (WidgetTester tester) async {
      final extraItems = [
        CurrencyModel(
          id: '3',
          nominal: 1,
          name: 'Японская иена',
          symbol: 'JPY',
          value: 0.5274,
          previousValue: 0.5200,
        ),
      ];

      when(mockCurrencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD'))).thenAnswer((_) async => CurrencyPage(items: currencyItems, page: 0, hasMore: true));
      when(mockCurrencyRepository.saveCurrencyList(any)).thenAnswer((_) async {});

      // Определяем ответ по номеру страницы в запросе
      int callCount = 0;
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((Invocation invocation) {
        if (callCount == 0) {
          callCount++;
          return Future.value(CurrencyPage(items: currencyItems, page: 0, hasMore: true));
        } else {
          return Future.value(CurrencyPage(items: extraItems, page: 1, hasMore: false));
        }
      });

      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();
      expect(find.byType(ElevatedButton), findsOneWidget);

      await tester.tap(find.byType(ElevatedButton));
      await tester.pumpAndSettle();

      expect(find.byType(CurrencyCard), findsNWidgets(currencyItems.length + extraItems.length));
      expect(find.text('JPY'), findsOneWidget);
    });
  });
}
